describe('Character Count on Textarea with 500-character Limit', () => {
  beforeEach(() => {
    cy.visit('/textarea-validation');
  });

  it('should display character count and update as user types', () => {
    // Verify initial state: empty textarea with 0 characters displayed
    cy.get('[data-testid="textarea-input"]').should('be.visible');
    cy.get('[data-testid="character-count"]').should('contain', '0/500');

    // Type 100 characters
    cy.get('[data-testid="textarea-input"]').type('This is a test of the character count limit.');
    cy.get('[data-testid="character-count"]').should('contain', '100/500');

    // Verify character count updates in real-time
    cy.get('[data-testid="textarea-input"]').type('This is a longer test to see if the count updates correctly.');
    cy.get('[data-testid="character-count"]').should('contain', '200/500');

    // Verify character count does not exceed 500
    cy.get('[data-testid="textarea-input"]').type('This is a very long test string to ensure the limit is respected.');
    cy.get('[data-testid="character-count"]').should('contain', '500/500');

    // Verify character count is displayed even when textarea is empty
    cy.get('[data-testid="textarea-input"]').clear();
    cy.get('[data-testid="character-count"]').should('contain', '0/500');

    // Verify character count is not displayed when textarea is not focused
    cy.get('[data-testid="textarea-input"]').blur();
    cy.get('[data-testid="character-count"]').should('not.exist');

    // Verify character count is visible when textarea is focused
    cy.get('[data-testid="textarea-input"]').focus();
    cy.get('[data-testid="character-count"]').should('be.visible');

    // Verify character count is updated when textarea loses focus
    cy.get('[data-testid="textarea-input"]').blur();
    cy.get('[data-testid="character-count"]').should('contain', '0/500');
  });

  it('should prevent pasting text exceeding 500 characters and display error message', () => {
    // Verify initial state: empty textarea with 0 characters displayed
    cy.get('[data-testid="textarea-input"]').should('be.visible');
    cy.get('[data-testid="character-count"]').should('contain', '0/500');

    // Type 499 characters
    cy.get('[data-testid="textarea-input"]').type('This is a test of the character count limit.');
    cy.get('[data-testid="character-count"]').should('contain', '499/500');

    // Attempt to paste text exceeding 500 characters
    cy.get('[data-testid="textarea-input"]').paste('This is a very long text that exceeds the limit.');

    // Verify character count does not exceed 500
    cy.get('[data-testid="character-count"]').should('contain', '500/500');

    // Verify error message is displayed when pasting exceeds limit
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Cannot paste text longer than 500 characters');

    // Verify error message disappears when pasting valid text
    cy.get('[data-testid="textarea-input"]').clear();
    cy.get('[data-testid="textarea-input"]').type('This is a valid test');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
